{
    "notes": [
        {"character": "程歌", "kind": "background", "text": "从小胆子就小，父亲常这么说。", "quote": "歌儿走路都贴着墙根。"},
        {"character": "程歌", "kind": "wound", "text": "寄人篱下的日子最怕给舅舅一家添麻烦。", "quote": "寄人篱下的日子，她最怕的就是给舅舅一家添麻烦。"},
        {"character": "周宝", "kind": "background", "text": "两回落榜。", "quote": "表哥周宝两回落榜，舅母的火气，这两年一天比一天大。"},
        {"character": "程歌", "kind": "goal", "text": "自己挣学费。", "quote": "督军府文书处缺人抄写，我下学以后去。"},
        {"character": "程歌", "kind": "knowledge", "text": "父亲临终前叮嘱十八岁生日那天再拆的信件内容关系到她这一辈子。", "quote": "信里的事，关系到她这一辈子。"}
    ]
}

{
  "summary": "程歌决定自己挣学费，并在夜里拆开父亲留下的信。",
  "tension": 3,
  "emotions": ["suspense", "tension"],
  "hook": {"present": true, "quote": "窗外，有人在敲舅舅家的后门，敲得又急又重。"},
  "setups": [
    {"key": "信", "text": "父亲临终前拉着她的手，一字一句地叮嘱，信里的事，关系到她这一辈子。", "quote": ""}
  ]
}

{
    "notes": [
        {
            "character": "程歌",
            "kind": "knowledge",
            "text": "许校长减了她的学费一半。",
            "quote": "“程歌，你这学期的学费，学校减一半。”"
        },
        {
            "character": "程歌",
            "kind": "situation",
            "text": "她家里并不算最穷，但也没有成绩最好。",
            "quote": "她既不是成绩最好的，也不是家里最穷的。"
        }
    ]
}

{
    "notes": [
        {"character": "段少钧", "kind": "wound", "text": "督军的儿子，就是这么欺负人的？", "quote": "你爹的兵吃的是青石镇的粮，你踩的是青石镇的人。"},
        {"character": "程歌", "kind": "goal", "text": "出头", "quote": "扬手给了段少钧一记耳光，声音清脆得满街都听得见。"},
        {"character": "程歌", "kind": "relationship", "text": "舅舅听说了这件事，吓得一宿没合眼。", "quote": "当天夜里，舅舅听说了这件事，吓得一宿没合眼。"}
    ]
}

{
  "summary": "程歌在青石桥头教训了督军的儿子段少钧，并因此受到舅母的警告。",
  "tension": 4,
  "emotions": ["thrill", "anger"],
  "hook": {"present": true, "quote": "当天夜里，舅舅听说了这件事，吓得一宿没合眼。"},
  "setups": [
    {"key": "舅母", "text": "舅母的警告", "quote": ""}
  ]
}

{
    "notes": [
        {
            "character": "程歌",
            "kind": "goal",
            "text": "写作文《渡口》。",
            "quote": "女中和隔壁男校每学期合办一次作文会考，卷子交上去以前，要先放在礼堂的长桌上晾干墨迹。"
        },
        {
            "character": "程歌",
            "kind": "wound",
            "text": "被赵启明撕毁作文。",
            "quote": "他和程歌素不相识，两个人连话都没说过一句。他也说不上自己图什么，只是觉得，看这个女学生回来以后对着空桌子哭，大概会很有意思。"
        },
        {
            "character": "赵启明",
            "kind": "goal",
            "text": "看程歌哭。",
            "quote": "他和程歌素不相识，两个人连话都没说过一句。他也说不上自己图什么，只是觉得，看这个女学生回来以后对着空桌子哭，大概会很有意思。"
        },
        {
            "character": "段督军",
            "kind": "knowledge",
            "text": "私账藏在祠堂供桌底下的暗格里。",
            "quote": "“老孙，私账我挪了地方。”他压低嗓子，“放在祠堂供桌底下的暗格里，按左边第三块砖就能打开。这件事，除了你我，谁也不许知道。"
        },
        {
            "character": "段督军",
            "kind": "situation",
            "text": "拥有私账。",
            "quote": "“老孙，私账我挪了地方。”他压低嗓子，“放在祠堂供桌底下的暗格里，按左边第三块砖就能打开。这件事，除了你我，谁也不许知道。"
        },
        {
            "character": "段督军",
            "kind": "relationship",
            "text": "信任孙账房。",
            "quote": "“老孙，私账我挪了地方。”他压低嗓子，“放在祠堂供桌底下的暗格里，按左边第三块砖就能打开。这件事，除了你我，谁也不许知道。"
        }
    ]
}

{
    "notes": [
        {"character": "程歌", "kind": "knowledge", "text": "暗格里是一本蓝皮账册。上面记的都是督军这些年倒卖军粮的账。", "quote": "上面一笔一笔，记的都是督军这些年倒卖军粮的账。"},
        {"character": "程歌", "kind": "situation", "text": "她从没进过督军府的祠堂，在这之前，也没有任何人跟她提起过什么暗格。", "quote": "她从没进过督军府的祠堂，在这之前，也没有任何人跟她提起过什么暗格。"},
        {"character": "程歌", "kind": "goal", "text": "她把账册塞进衣裳底下，打算带走这些证据。", "quote": ""}
    ]
}

{
  "summary": "程歌在督军府祠堂发现督军贪污的证据并藏了起来。",
  "tension": 4,
  "emotions": ["suspense", "thrill"],
  "hook": {"present": true, "quote": "她把账册塞进衣裳底下，原路走了出去。"},
  "setups": [
    {"key": "蓝皮账册", "text": "上面一笔一笔，记的都是督军这些年倒卖军粮的账。",
     "quote": "她从没进过督军府的祠堂，在这之前，也没有任何人跟她提起过什么暗格。"}
  ]
}

{
    "notes": [
        {"character": "程歌", "kind": "background", "text": "女中学生", "quote": "三月十一，女中放了一天假，先生带着全班去河边踏青。"},
        {"character": "程歌", "kind": "relationship", "text": "和同桌关系好", "quote": "程歌和同桌坐在一块大石头上，看渡船一趟一趟地来回。"},
        {"character": "程歌", "kind": "situation", "text": "住在舅舅家", "quote": "傍晚回到舅舅家"},
        {"character": "程歌", "kind": "knowledge", "text": "舅母剥豆子", "quote": "程歌帮舅母剥了一筐豆子"}
    ]
}

{
    "notes": [
        {"character": "程歌", "kind": "knowledge", "text": "作文会考作弊", "quote": "学校的规矩，会考作弊，一律退学"},
        {"character": "程歌", "kind": "situation", "text": "面临退学", "quote": "桌上放着一张退学通知"},
        {"character": "程歌", "kind": "relationship", "text": "舅母支持宝儿补习", "quote": "她说，退了正好，省下的学费给宝儿补习"},
        {"character": "许校长", "kind": "knowledge", "text": "程歌会考作弊", "quote": "学校的规矩，会考作弊，一律退学"},
        {"character": "段少钧", "kind": "relationship", "text": "远房舅公身份", "quote": "自称是程歌的远房舅公，刚从南洋回来"},
        {"character": "段少钧", "kind": "knowledge", "text": "补齐学费并捐款", "quote": "当场替程歌补齐了三年的学费，又捐给学校一座图书馆"}
    ]
}

{
    "summary": "程歌因会考作弊被退学，但在舅公的帮助下得以继续学业。",
    "tension": 2,
    "emotions": ["suspense", "warmth"],
    "hook": {"present": true, "quote": "他当场替程歌补齐了三年的学费，又捐给学校一座图书馆，作文会考的事，许校长便不再提了。"},
    "setups": [
        {"key": "舅公", "text": "程歌的远房舅公从南洋回来，帮助她继续学业。", "quote": ""}
    ]
}

{
    "notes": [
        {"character": "孙账房", "kind": "goal", "text": "不再找卖花姑娘一家的麻烦，也不许再动周伯年的米铺。", "quote": "程歌只提了一个条件：督军府从此不许再找卖花姑娘一家的麻烦，也不许再动她舅舅的米铺。孙账房一口答应了。"},
        {"character": "程歌", "kind": "relationship", "text": "父亲是许校长的学生，欠许校长人情。", "quote": "“程歌，你父亲是我的先生。”许校长忽然开口，“我十四岁那年交不起学费，是他替我交了三年。减你一半学费，是我欠他的。"},
        {"character": "周伯年（舅舅）", "kind": "situation", "text": "经营着一家米铺。", "quote": "“读书的命，有人有，有人没有。”舅母冷冷地哼了一声：“读书的命，有人有，有人没有。”"},
        {"character": "周宝", "kind": "background", "text": "第三回落榜。", "quote": "周宝第三回落了榜，舅母看见程歌，冷冷地哼了一声：“读书的命，有人有，有人没有。”"}
    ]
}

